import{_ as o,l as s,o as e,c as n,v as i,p as l,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"蓄水池抽样","description":"","frontmatter":{"title":"蓄水池抽样","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reservoir-sampling.md","filePath":"cs/reservoir-sampling.md","lastUpdated":1789023840000}'),c={name:"cs/reservoir-sampling.md"};function m(E,a,A,_,k,u){const r=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="蓄水池抽样" tabindex="-1">蓄水池抽样 <a class="header-anchor" href="#蓄水池抽样" aria-label="Permalink to &quot;蓄水池抽样&quot;">​</a></h1><div class="epigraph"><p>流长度事先不知道：前 $k$ 个全进池，第 $i$ 个以 $k/i$ 替换池中均匀一个；结束时每个元素等概率在池里。</p><footer>—— 据 Vitter, Random Sampling with a Reservoir, ACM TOMS 1985；Knuth, TAOCP 卷 2 整理</footer></div><p><a href="/cs/minhash-lsh">上一课</a> 假定能扫集合或签名。<a href="/cs/array-random-access">数组</a> 已知 \\(n\\) 可直接抽下标。数据流、日志一行行来，\\(n\\) 未知或太大。本课不入 LSH 桶。缺口是蓄水池：固定 \\(k\\) 个槽，单遍均匀样本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要大小 \\(k\\) 的无放回均匀子集（或每个位置等概率）。若 \\(n\\) 知，Fisher–Yates 前 \\(k\\) 即可。\\(n\\) 不知：Algorithm R：遇到第 \\(i\\) 个（\\(i\\gt k\\)），以 \\(k/i\\) 决定是否入选，入选则均匀替换池中一席。归纳：看完 \\(i\\) 个后池是前 \\(i\\) 个的均匀 \\(k\\) 子集。缺口是<strong>用递推概率代替预先 \\(n\\)</strong>。</p><p><span class="marginnote">Vitter, <em>ACM Trans. Math. Software</em>, 1985，含跳过几何随机数的加速。Knuth 卷 2 抽样。加权蓄水池（Efraimidis）点名不展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现注意 \\(i\\) 用浮点算 \\(k/i\\) 的精度，或用整数技巧。跳过：一次生成「下一个替换发生在哪」，少抛硬币。并行：多机蓄水池再合并要加权，不是简单拼接。</p>',8)),(e(),l(h,null,{default:t(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%AC%AC%20i%20%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%20--%3E%20P%5B%22%E4%BB%A5%20k%2Fi%20%E5%85%A5%E9%80%89%22%5D%0A%20%20P%20--%3E%20REP%5B%22%E5%9D%87%E5%8C%80%E6%9B%BF%E6%8D%A2%E6%B1%A0%E4%B8%AD%E4%B8%80%E5%B8%AD%22%5D%0A%20%20POOL%5B%22%E6%B1%A0%E5%A4%A7%E5%B0%8F%E6%81%92%E4%B8%BA%20k%22%5D%20--%3E%20UNIF%5B%22%E5%89%8D%20i%20%E4%B8%AA%E7%9A%84%E5%9D%87%E5%8C%80%E5%AD%90%E9%9B%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>与 HLL：HLL 不保留元素；蓄水池保留真实记录便于事后分析。与 CM：CM 估频次不给均匀样本。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>证明对 \\(i\\) 归纳：老元素留在池中的概率正确下降。第 \\(i\\) 个进入概率 \\(k/i\\)，对称性得均匀。不要在未知 \\(n\\) 时先 <code>list.append</code> 再 <code>random.choice</code>——那不是流算法。</p><p>分位数要的是分布形状不是均匀元素：下一课 t-digest。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写分布式精确合并的全部协议。有放回、滑动窗口蓄水池是变体。不要抽「限价簿订单」当例子——本栏避开 LOB。</p><p>后课默认：未知 \\(n\\) 均匀 \\(k\\) 样本用蓄水池。流上分位数用 t-digest。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蓄水池：单遍、固定 \\(k\\)、均匀。</li><li>第 \\(i\\) 个以 \\(k/i\\) 替换。</li><li>下一课近似分位数摘要。</li><li>出处：Vitter, <em>TOMS</em>, 1985；Knuth 卷 2。</li></ul>',9))])}const T=o(c,[["render",m]]);export{f as __pageData,T as default};
